## Why This Is Asked
This question tests the fundamental understanding of combining data structures to achieve O(1) operations while maintaining an ordering constraint. It evaluates knowledge of hash map + linked list patterns and eviction logic commonly used in caching systems.

## Key Concepts
- HashMap for O(1) key-to-node lookups
- Doubly linked list for maintaining recency order
- Node manipulation for constant-time recency updates
- Edge case handling: missing keys, capacity limits, and duplicate operations

## Code Example
```javascript
class LRUCache {
  constructor(capacity) {
    this.capacity = capacity;
    this.cache = new Map();
    this.head = { prev: null, next: null };
    this.tail = { prev: null, next: null };
    this.head.next = this.tail;
    this.tail.prev = this.head;
  }

  get(key) {
    if (!this.cache.has(key)) return -1;
    const node = this.cache.get(key);
    this._moveToHead(node);
    return node.value;
  }

  put(key, value) {
    if (this.cache.has(key)) {
      const node = this.cache.get(key);
      node.value = value;
      this._moveToHead(node);
    } else {
      const newNode = { key, value, prev: null, next: null };
      this.cache.set(key, newNode);
      this._addToHead(newNode);
      if (this.cache.size > this.capacity) {
        this._removeTail();
      }
    }
  }

  _moveToHead(node) {
    this._removeNode(node);
    this._addToHead(node);
  }

  _addToHead(node) {
    node.prev = this.head;
    node.next = this.head.next;
    this.head.next.prev = node;
    this.head.next = node;
  }

  _removeNode(node) {
    node.prev.next = node.next;
    node.next.prev = node.prev;
  }

  _removeTail() {
    const node = this.tail.prev;
    this._removeNode(node);
    this.cache.delete(node.key);
  }
}
```

## Why This Is Asked
This question tests understanding of order statistics in dynamic multisets with duplicates and efficient prefix queries—skills fundamental to database indexing and ranking problems.

## Key Concepts
- **Balanced BST with per-node counts and subtree sizes** enables O(log n) operations
- **Handling duplicates via dupCount** avoids unnecessary node creation
- **getRank as a prefix-count query** is analogous to order statistics

## Code Example
```javascript
class Node {
  constructor(key) {
    this.key = key;
    this.dup = 1;
    this.left = null;
    this.right = null;
  }

  get size() {
    return this.dup + (this.left?.size ?? 0) + (this.right?.size ?? 0);
  }
}

class Treap {
  constructor() {
    this.root = null;
  }

  insert(key) {
    this.root = this._insert(this.root, key);
  }

  _insert(node, key) {
    if (!node) return new Node(key);
    if (key === node.key) {
      node.dup++;
    } else if (key < node.key) {
      node.left = this._insert(node.left, key);
    } else {
      node.right = this._insert(node.right, key);
    }
    return node;
  }

  erase(key) {
    this.root = this._erase(this.root, key);
  }

  _erase(node, key) {
    if (!node) return null;
    if (key === node.key) {
      node.dup--;
      if (node.dup === 0) return this._merge(node.left, node.right);
    } else if (key < node.key) {
      node.left = this._erase(node.left, key);
    } else {
      node.right = this._erase(node.right, key);
    }
    return node;
  }

  _merge(left, right) {
    if (!left || !right) return left ?? right;
    // Simplified: in a real Treap, merge by priority
    return this._bstMerge(left, right);
  }

  _bstMerge(left, right) {
    if (!left) return right;
    if (!right) return left;
    const node = left;
    node.right = this._bstMerge(node.right, right);
    return node;
  }

  getRank(v) {
    return this._getRank(this.root, v);
  }

  _getRank(node, v) {
    if (!node) return 0;
    if (v < node.key) {
      return this._getRank(node.left, v);
    }
    const leftSize = node.left?.size ?? 0;
    return leftSize + node.dup + this._getRank(node.right, v);
  }
}
```
